function longestConsecutive(nums: number[]): number {
  // Множество даёт проверку «есть ли число» за O(1) и убирает дубликаты
  const set = new Set(nums);
  let best = 0;

  for (const x of set) {
    // Начинаем считать только с НАЧАЛА последовательности:
    // если x - 1 есть, то x — не начало, его посчитают с более раннего числа
    if (set.has(x - 1)) continue;

    // Идём вверх, пока числа подряд есть в множестве
    let length = 1;
    while (set.has(x + length)) {
      length++;
    }

    best = Math.max(best, length);
  }

  return best;
}

// Время: O(n) — каждое число проверяется во while не более одного раза
// Память: O(n) — множество
